#include "audio/JuceAudioBackend.h"
namespace jeff::daw {JuceAudioBackend::JuceAudioBackend(AudioEngine&e):engine(e){manager.addAudioCallback(this);}JuceAudioBackend::~JuceAudioBackend(){manager.removeAudioCallback(this);}AudioConfigurationResult JuceAudioBackend::configure(const AudioConfiguration&c){auto err=manager.initialise(c.inputChannels,c.outputChannels,nullptr,true);if(err.isNotEmpty())return{false,err.toStdString()};auto s=manager.getAudioDeviceSetup();s.sampleRate=c.sampleRate;s.bufferSize=c.bufferSize;err=manager.setAudioDeviceSetup(s,true);return{err.isEmpty(),err.toStdString()};}void JuceAudioBackend::audioDeviceIOCallbackWithContext(const float*const*,int,float*const*out,int n,int samples,const juce::AudioIODeviceCallbackContext&){engine.processBlock(out,n,samples);}void JuceAudioBackend::audioDeviceAboutToStart(juce::AudioIODevice*d){engine.prepare(d->getCurrentSampleRate(),d->getCurrentBufferSizeSamples(),d->getActiveOutputChannels().countNumberOfSetBits());}}
